import os
import re
import requests
from requests.auth import HTTPBasicAuth
from dotenv import load_dotenv

load_dotenv()

# Priority mapping — P1 → Jira "Highest", etc.
PRIORITY_MAP = {
    "P1": "Highest",
    "P2": "High",
    "P3": "Medium",
}

# Severity → Jira label
SEVERITY_LABEL_MAP = {
    "CRITICAL": "sev-critical",
    "HIGH":     "sev-high",
    "MEDIUM":   "sev-medium",
    "LOW":      "sev-low",
}


def _get_config() -> dict:
    """Loads and validates Jira config from environment."""
    config = {
        "base_url":    os.getenv("JIRA_BASE_URL", "").rstrip("/"),
        "email":       os.getenv("JIRA_EMAIL", ""),
        "api_token":   os.getenv("JIRA_API_TOKEN", ""),
        "project_key": os.getenv("JIRA_PROJECT_KEY", "ENG"),
    }

    missing = [k for k, v in config.items() if not v]
    if missing:
        raise ValueError(
            f"Missing Jira config in .env: {', '.join(missing).upper()}\n"
            "  See .env.example for setup instructions."
        )
    return config


def _extract_action_items(raw_text: str) -> list[dict]:
    """Parse action items from post-mortem text."""
    items = []
    lines = raw_text.split("\n")
    in_actions = False
    current_item = None

    for line in lines:
        if "ACTION ITEMS" in line.upper():
            in_actions = True
            continue
        if in_actions:
            if any(line.strip().startswith(s) for s in (
                "LESSONS", "CONTRIBUTING", "SUMMARY", "TIMELINE", "ROOT CAUSE"
            )):
                break

            match = re.match(r"\[(P[123])\]\s+(.+)", line.strip())
            if match:
                if current_item:
                    items.append(current_item)
                current_item = {
                    "priority":    match.group(1),
                    "description": match.group(2).strip(),
                    "owner":       "",
                    "due_date":    "",
                }
            elif current_item and line.strip().startswith("Owner:"):
                owner_match = re.search(r"Owner:\s*([^·]+)", line)
                due_match   = re.search(r"Due:\s*(.+)$", line)
                if owner_match:
                    current_item["owner"] = owner_match.group(1).strip()
                if due_match:
                    current_item["due_date"] = due_match.group(1).strip()

    if current_item:
        items.append(current_item)
    return items


def _extract_field(raw_text: str, field: str) -> str:
    match = re.search(rf"^{field}:\s*(.+)$", raw_text, re.MULTILINE)
    return match.group(1).strip() if match else ""


def _build_ticket_description(item: dict, title: str, severity: str, postmortem_id: int = None) -> dict:
    """Builds the Jira ticket description in Atlassian Document Format (ADF)."""
    lines = [
        f"*Incident:* {title}",
        f"*Severity:* {severity}",
        f"*Priority:* {item['priority']}",
        f"*Suggested Owner:* {item['owner'] or 'Unassigned'}",
        f"*Suggested Due Date:* {item['due_date'] or 'TBD'}",
        "",
        "----",
        "",
        f"*Action Item:* {item['description']}",
        "",
        "_Generated by oneport-postmortem. Do not edit this description — it is auto-generated._",
    ]
    if postmortem_id:
        lines.append(f"_Post-mortem DB ID: #{postmortem_id}_")

    return {
        "type":    "doc",
        "version": 1,
        "content": [
            {
                "type":    "paragraph",
                "content": [{"type": "text", "text": line}]
            }
            for line in lines
        ]
    }


def create_jira_tickets(raw_text: str, postmortem_id: int = None) -> list[dict]:
    """
    Parses action items from a post-mortem and creates Jira tickets.
    Returns a list of created ticket results with key, url, and status.
    """
    config = _get_config()
    auth   = HTTPBasicAuth(config["email"], config["api_token"])
    headers = {
        "Accept":       "application/json",
        "Content-Type": "application/json",
    }

    title    = _extract_field(raw_text, "TITLE") or "Incident"
    severity = _extract_field(raw_text, "SEVERITY") or "UNKNOWN"
    items    = _extract_action_items(raw_text)

    if not items:
        return []

    results = []

    for item in items:
        summary = f"[Post-Mortem] [{item['priority']}] {item['description']}"
        # Jira summary max is 255 chars
        if len(summary) > 255:
            summary = summary[:252] + "..."

        payload = {
            "fields": {
                "project":     {"key": config["project_key"]},
                "summary":     summary,
                "description": _build_ticket_description(
                    item, title, severity, postmortem_id
                ),
                "issuetype":   {"name": "Task"},
                "priority":    {"name": PRIORITY_MAP.get(item["priority"], "Medium")},
                "labels":      [
                    "post-mortem",
                    "oneport",
                    SEVERITY_LABEL_MAP.get(severity, "sev-unknown"),
                ],
            }
        }

        try:
            response = requests.post(
                f"{config['base_url']}/rest/api/3/issue",
                json=payload,
                headers=headers,
                auth=auth,
                timeout=10,
            )
            response.raise_for_status()
            data = response.json()
            ticket_key = data.get("key", "?")
            ticket_url = f"{config['base_url']}/browse/{ticket_key}"

            results.append({
                "priority":    item["priority"],
                "description": item["description"],
                "key":         ticket_key,
                "url":         ticket_url,
                "status":      "created",
            })

        except requests.exceptions.HTTPError as e:
            error_detail = ""
            try:
                error_detail = response.json().get("errorMessages", [str(e)])[0]
            except Exception:
                error_detail = str(e)
            results.append({
                "priority":    item["priority"],
                "description": item["description"],
                "key":         None,
                "url":         None,
                "status":      f"failed: {error_detail}",
            })

        except requests.exceptions.RequestException as e:
            results.append({
                "priority":    item["priority"],
                "description": item["description"],
                "key":         None,
                "url":         None,
                "status":      f"failed: {str(e)}",
            })

    return results


def test_jira_connection() -> tuple[bool, str]:
    """Tests that Jira credentials are valid. Returns (success, message)."""
    try:
        config  = _get_config()
        auth    = HTTPBasicAuth(config["email"], config["api_token"])
        headers = {"Accept": "application/json"}

        response = requests.get(
            f"{config['base_url']}/rest/api/3/myself",
            headers=headers,
            auth=auth,
            timeout=8,
        )
        response.raise_for_status()
        name = response.json().get("displayName", "Unknown")
        return True, f"Connected as: {name}"

    except requests.exceptions.HTTPError:
        return False, "Auth failed — check JIRA_EMAIL and JIRA_API_TOKEN in .env"
    except requests.exceptions.ConnectionError:
        return False, "Could not reach Jira — check JIRA_BASE_URL in .env"
    except ValueError as e:
        return False, str(e)